      'eng-2-1': { missionTitle: "ഓം നിയമം - വോൾട്ടേജ്", story: "I = 2A, R = 5Ω ആയാൽ V = I × R ഉപയോഗിച്ച് വോൾട്ടേജ് V കാണുക.", primaryConcept: "ഓം നിയമം (Ohm's Law)", learningObjective: "V = I × R പ്രയോഗിക്കുക.", missionObjective: "വോൾട്ടേജ് V കാണുക.", hint: "V = 2 × 5 = 10 വോൾട്ട്.", feedbackIncorrect: "V = 2 × 5 = 10V.", logicPremise: "V = I × R. I = 2A, R = 5Ω ആയാൽ V = ?", logicOptions: ["7V", "10V", "12V", "25V"], logicAnswer: "10V" },
      'eng-2-2': { missionTitle: "സീരീസ് സർക്യൂട്ട്", story: "സീരീസ് സർക്യൂട്ടിൽ ഒരു ബൾബ് കേടായാൽ മറ്റ് ബൾബുകൾക്ക് എന്ത് സംഭവിക്കും?", primaryConcept: "സീരീസ് സർക്യൂട്ടുകൾ (Series)", learningObjective: "സീരീസ് ബന്ധം മനസ്സിലാക്കുക.", missionObjective: "ഫലം കാണുക.", hint: "സീരീസിൽ ഒരു ബൾബ് കേടായാൽ കറന്റ് പൂർണ്ണമായി നിലയ്ക്കും.", feedbackIncorrect: "സീരീസ് സർക്യൂട്ടിൽ ഒരു ബൾബ് പോയാൽ ബാക്കിയെല്ലാം അണയും.", logicPremise: "സീരീസ് സർക്യൂട്ടിൽ 1 ബൾബ് കേടായാൽ ബാക്കിയുള്ളവ...", logicOptions: ["അണയും (Turn off)", "കൂടുതൽ പ്രകാശിക്കും", "മിന്നും", "പൊട്ടിത്തെറിക്കും"], logicAnswer: "അണയും (Turn off)" },
