      'eng-2-4': { missionTitle: "ഇലക്ട്രിക്കൽ പവർ", story: "V = 12V, I = 3A ആയാൽ P = V × I ഉപയോഗിച്ച് പവർ P കാണുക.", primaryConcept: "ഇലക്ട്രിക്കൽ പവർ", learningObjective: "P = V × I പ്രയോഗിക്കുക.", missionObjective: "പവർ P കാണുക.", hint: "P = 12 × 3 = 36 വാട്ട്സ്.", feedbackIncorrect: "P = 12 × 3 = 36W.", logicPremise: "P = V × I. V = 12V, I = 3A ആയാൽ പവർ P = ?", logicOptions: ["15W", "24W", "36W", "48W"], logicAnswer: "36W" },
