      'eng-3-3': { missionTitle: "ന്യൂമാറ്റിക് സിസ്റ്റം", story: "ന്യൂമാറ്റിക് സിസ്റ്റങ്ങൾ ചലനത്തിനായി ഏത് മാധ്യമമാണ് ഉപയോഗിക്കുന്നത്?", primaryConcept: "ന്യൂമാറ്റിക്സ് (Pneumatics)", learningObjective: "അമർത്തിയ വായു തിരിച്ചറിയുക.", missionObjective: "മാധ്യമം കാണുക.", hint: "ന്യൂമാറ്റിക്സ് അമർത്തിയ വായു ഉപയോഗിക്കുന്നു.", feedbackIncorrect: "ന്യൂമാറ്റിക് സിസ്റ്റങ്ങൾ അമർത്തിയ വായു ഉപയോഗിക്കുന്നു.", logicPremise: "ന്യൂമാറ്റിക് ആക്ചുവേറ്ററുകൾ ചലനത്തിന് ഉപയോഗിക്കുന്നത് എന്ത്?", logicOptions: ["അമർത്തിയ വായു (Compressed air)", "ഓയിൽ", "വൈദ്യുതി മാത്രം", "ആവി"], logicAnswer: "അമർത്തിയ വായു (Compressed air)" },
